import java.util.HashSet;
import java.util.Set;

public class SecurityAuditRegistry {
    private final Set<String> activeSecurityBadges = new HashSet<>();

    public boolean issueBadge(String badgeId) {
        if (badgeId == null || badgeId.isBlank()) {
            throw new IllegalArgumentException("Badge ID cannot be blank");
        }
        // add() returns false if already present
        return activeSecurityBadges.add(badgeId);
    }

    public boolean isBadgeActive(String badgeId) {
        return activeSecurityBadges.contains(badgeId);
    }

    public int totalActiveBadges() {
        return activeSecurityBadges.size();
    }

    public static void main(String[] args) {
        SecurityAuditRegistry registry = new SecurityAuditRegistry();
        System.out.println("Registering SEC-001: " + registry.issueBadge("SEC-001"));
        System.out.println("Registering SEC-002: " + registry.issueBadge("SEC-002"));
        System.out.println("Duplicate SEC-001: " + registry.issueBadge("SEC-001"));

        System.out.println("Total Active Badges: " + registry.totalActiveBadges());
        System.out.println("Is SEC-002 valid? " + registry.isBadgeActive("SEC-002"));
    }
}

